async function createAllDrafts(){if(!ebay?.ready){setEbayMessage("Complete eBay Sandbox seller setup before creating drafts.");return}const pending=groups.filter(item=>!offers[item.id]&&draftReady(item.id));if(!pending.length){setEbayMessage("No ready items are waiting for a Production draft. Review any blocked item specifics first.");return}setCreatingAll(true);let completed=0,failed=0;for(const item of pending){if(await createEbayDraft(item.id,true))completed++;else failed++}setCreatingAll(false);setEbayMessage(`${completed} Production draft${completed===1?"":"s"} created${failed?`; ${failed} item${failed===1?"":"s"} needs retry`:""}. Nothing was published.`)}async function load(files:File[]){setBusy(true);const r=analyze(await Promise.all(files.map(read)));setPhotos(r.photos);setGroups(r.groups);setFacts({});setSpecifics({});setGenerationStatus({});setDraftErrors({});setDrafts({});setTitles({});setOfferInputs({});setOffers({});setGroup(1);setPicked(new Set());setBusy(false)}function choose(e:ChangeEvent<HTMLInputElement>){load(Array.from(e.target.files??[]))}function open(id:number){setGroup(id);setPicked(new Set(photos.filter(p=>p.cluster===id).map(p=>p.id)))}function toggle(id:string){setPicked(old=>{const n=new Set(old);n.has(id)?n.delete(id):n.add(id);return n})}function assign(){setPhotos(old=>old.map(p=>picked.has(p.id)?{...p,cluster:group}:p.cluster===group?{...p,cluster:0}:p));setPicked(new Set())}function regroup(){const r=analyze(photos.map(p=>({...p,cluster:0})));setPhotos(r.photos);setGroups(r.groups);setGroup(1);setPicked(new Set())}function add(){const id=Math.max(0,...groups.map(g=>g.id))+1;setGroups(old=>[...old,{id,name:`Proposed item ${id}`}]);setGroup(id);setPicked(new Set())}
